import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const canvas=document.querySelector('#game');
const scene=new THREE.Scene();
scene.background=new THREE.Color(0x101715);scene.fog=new THREE.FogExp2(0x111815,.033);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,100);camera.position.set(0,4,8);
const renderer=new THREE.WebGLRenderer({canvas,antialias:false,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;
scene.add(new THREE.HemisphereLight(0xb7c9bd,0x151713,1.5));const moonLight=new THREE.DirectionalLight(0xc5c8d6,2.1);moonLight.position.set(-7,12,4);moonLight.castShadow=true;moonLight.shadow.mapSize.set(1024,1024);scene.add(moonLight);const glow=new THREE.PointLight(0x8570ae,10,16,2);glow.position.set(0,2,-7);scene.add(glow);
const mat=(color,roughness=.9,opts={})=>new THREE.MeshStandardMaterial({color,roughness,...opts});
const mats={soil:mat(0x282e29),soil2:mat(0x34372e),bark:mat(0x262925),bark2:mat(0x3c3a32),moss:mat(0x354138),stone:mat(0x53544b),stoneDark:mat(0x333832),water:mat(0x253938,.22,{metalness:.2}),gold:mat(0xb59a69,.48,{emissive:0x493717,emissiveIntensity:.3}),robe:mat(0x171b1b),cloak:mat(0x302b36),skin:mat(0xb39b85),hair:mat(0x111313),white:mat(0xd8d8cf),eye:mat(0xaaa18d),moth:mat(0xd8d5b9,.65,{emissive:0x98937d,emissiveIntensity:.6}),relic:mat(0x9a7f61,.38,{emissive:0x3c2917,emissiveIntensity:.5})};
const groundGeo=new THREE.PlaneGeometry(44,58,50,62);groundGeo.rotateX(-Math.PI/2);const pos=groundGeo.attributes.position;for(let i=0;i<pos.count;i++){let x=pos.getX(i),z=pos.getZ(i);pos.setY(i,Math.sin(x*.48+z*.26)*.12+Math.sin(z*.75-x*.22)*.07);}groundGeo.computeVertexNormals();const ground=new THREE.Mesh(groundGeo,new THREE.MeshStandardMaterial({color:0xffffff,roughness:1,vertexColors:true}));const cols=[];for(let i=0;i<pos.count;i++){let x=pos.getX(i),z=pos.getZ(i),c=new THREE.Color(((Math.sin(x*2+z*2)*.5+.5)>.84)?0x45473c:0x252c28);c.multiplyScalar(.83+Math.random()*.32);cols.push(c.r,c.g,c.b);}groundGeo.setAttribute('color',new THREE.Float32BufferAttribute(cols,3));ground.position.set(0,-.16,-5);ground.receiveShadow=true;scene.add(ground);
const group=new THREE.Group();scene.add(group);
function addMesh(geo,material,x,y,z,sx=1,sy=1,sz=1,rot=0){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.rotation.y=rot;m.castShadow=true;m.receiveShadow=true;group.add(m);return m;}
function cylinderBetween(a,b,r1,r2,material,seg=7){const A=new THREE.Vector3(...a),B=new THREE.Vector3(...b),d=new THREE.Vector3().subVectors(B,A);let m=new THREE.Mesh(new THREE.CylinderGeometry(r2,r1,d.length(),seg),material);m.position.copy(A).add(B).multiplyScalar(.5);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());m.castShadow=true;m.receiveShadow=true;group.add(m);return m;}
function tree(x,z,h=5,seed=1){let lean=Math.sin(seed*17)*.9; cylinderBetween([x,0,z],[x+lean*.35,h*.52,z+Math.cos(seed)*.35],.42,.27,mats.bark,8);cylinderBetween([x+lean*.35,h*.52,z+Math.cos(seed)*.35],[x+lean,h,z+Math.cos(seed)*.65],.27,.045,mats.bark2,7);for(let b=0;b<3;b++){let side=b%2?1:-1,y=h*(.38+b*.15),end=[x+lean*.35+side*(.8+b*.2),y+.8,z+Math.cos(seed)*.35-.35];cylinderBetween([x+lean*.25,y,z],end,.16,.035,mats.bark,6);let tuft=addMesh(new THREE.IcosahedronGeometry(.7,1),b%2?mats.moss:mats.bark,x+lean*.35+side*1,y+.9,z-.4,1.2,.7,1);tuft.rotation.z=side*.2;}for(let r=0;r<4;r++){let a=r*Math.PI/2+seed; cylinderBetween([x,0,z],[x+Math.cos(a)*(.8+Math.random()*.35),-.02,z+Math.sin(a)*(.7+Math.random()*.3)],.16,.025,mats.bark,5);}}
for(let i=0;i<35;i++){let x=(Math.random()-.5)*36,z=-22+Math.random()*34;if(Math.abs(x)<4&&z>0)continue;tree(x,z,3.8+Math.random()*4,i+1);}
// Mud paths and scattered wet pools
function puddle(x,z,rx,rz){let p=addMesh(new THREE.CircleGeometry(1,20),mats.water,x,.005,z,rx,rz,1);p.rotation.x=-Math.PI/2;p.material.side=THREE.DoubleSide;}
[[0,-2,2,4],[-5,-8,2,5],[5,-9,2,4],[-10,-17,3,5],[10,-17,3,5],[0,4,3,2]].forEach(v=>puddle(...v));
for(let i=0;i<100;i++){let x=(Math.random()-.5)*35,z=-24+Math.random()*35;let rock=addMesh(new THREE.DodecahedronGeometry(.2+Math.random()*.45,0),Math.random()>.5?mats.stoneDark:mats.soil2,x,0,z,.7+Math.random(),.25+Math.random()*.5,.8+Math.random());rock.rotation.set(Math.random(),Math.random(),Math.random());}
// Ruin fragments and ring
for(let side of [-1,1]){for(let i=0;i<4;i++){let x=side*(4.6+i*.33),z=-5-i*1.35;let p=addMesh(new THREE.BoxGeometry(1.05,2.8,1),mats.stone,x,1.25,z,.85,Math.random()*.7+.7,.8);p.rotation.z=(Math.random()-.5)*.1;}for(let i=0;i<7;i++){let a=Math.PI*(i/6),x=side*6.7+Math.cos(a)*1.3,z=-9+Math.sin(a)*1.2;let s=addMesh(new THREE.BoxGeometry(.8,1.5,.7),mats.stoneDark,x,.6,z,.9,.8,.9);s.rotation.z=(Math.random()-.5)*.2;}}
// Carved standing monolith, front faces toward start
const monolith=addMesh(new THREE.BoxGeometry(1.25,3.5,.55),mats.stoneDark,0,1.58,-7);monolith.rotation.y=.11;const cap=addMesh(new THREE.ConeGeometry(.9,.65,4),mats.stone,0,3.65,-7);cap.rotation.y=Math.PI/4;
for(let i=0;i<4;i++){let line=addMesh(new THREE.BoxGeometry(.06,.68-i*.1,.035),mats.gold,-.27+i*.18,1.55,-6.705);line.rotation.z=(i%2?.4:-.35);}
// Relic pedestal and relic
addMesh(new THREE.CylinderGeometry(.8,.95,.45,8),mats.stoneDark,-7,.2,-12);addMesh(new THREE.CylinderGeometry(.56,.72,.28,8),mats.stone,-7,.55,-12);const relic=addMesh(new THREE.TorusKnotGeometry(.36,.09,48,8,2,3),mats.relic,-7,1.18,-12);relic.rotation.set(.5,.2,.3);const relicLight=new THREE.PointLight(0x9c7aa8,3,4);relicLight.position.set(-7,1.3,-12);scene.add(relicLight);
// Old woman in the clearing
const woman=new THREE.Group();woman.position.set(7,0,-13);woman.rotation.y=-.3;group.add(woman);function womanMesh(geo,ma,x,y,z,sx=1,sy=1,sz=1){let m=new THREE.Mesh(geo,ma);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;woman.add(m);return m;}womanMesh(new THREE.ConeGeometry(.66,2.1,7),mats.cloak,0,1.05,0,1,.95,1);womanMesh(new THREE.SphereGeometry(.35,10,8),mats.skin,0,2.3,-.03,.82,1,.8);womanMesh(new THREE.SphereGeometry(.38,8,6),mats.hair,0,2.52,.04,1.05,.8,1);womanMesh(new THREE.CylinderGeometry(.035,.05,1.5,6),mats.bark,.62,.75,.05);womanMesh(new THREE.SphereGeometry(.07,8,6),mats.gold,.62,1.55,.05);
// Branching path sign stones
for(let x of [-1,1]){for(let i=0;i<6;i++){let z=-15-i*1.15,px=x*(i*.55+.6);let st=addMesh(new THREE.BoxGeometry(.42,.18,.65),mats.stone,px,.05,z,.9,1,1);st.rotation.y=x*.18;}}
// Exit markers
const gates=[];for(const [x,color,label] of [[-9,0x8065a2,'EL SENDERO DEL ECO'],[9,0x9d8b63,'EL SENDERO DE LA SAL']]){let ring=new THREE.Mesh(new THREE.TorusGeometry(1.45,.07,7,32),new THREE.MeshStandardMaterial({color,emissive:color,emissiveIntensity:.75,transparent:true,opacity:.75}));ring.position.set(x,1.45,-22);scene.add(ring);let light=new THREE.PointLight(color,2.2,7);light.position.set(x,1.5,-22);scene.add(light);gates.push({x,z:-22,ring,light,label});}
// Character, actual articulated low-poly mesh
const player=new THREE.Group();scene.add(player);const avatar=new THREE.Group();player.add(avatar);
function body(geo,ma,x,y,z,sx=1,sy=1,sz=1){let m=new THREE.Mesh(geo,ma);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;avatar.add(m);return m;}
body(new THREE.CylinderGeometry(.2,.25,.72,8),mats.robe,0,.92,0,.9,1, .6);body(new THREE.SphereGeometry(.23,10,8),mats.skin,0,1.51,-.015,.82,.95,.8);body(new THREE.SphereGeometry(.25,10,7),mats.hair,0,1.66,.015,1.03,.8,1);body(new THREE.BoxGeometry(.055,.4,.06),mats.white,-.09,1.83,-.17,.7,1,1);
body(new THREE.ConeGeometry(.36,.48,7),mats.cloak,0,.72,.02,1,.9,.72);for(let s of [-1,1]){let leg=body(new THREE.CylinderGeometry(.09,.11,.62,7),mats.robe,s*.115,.34,0,1,1,1);let boot=body(new THREE.BoxGeometry(.19,.13,.32),mats.bark2,s*.115,.08,-.06);let arm=body(new THREE.CylinderGeometry(.075,.1,.54,7),mats.robe,s*.28,1.05,0);arm.rotation.z=s*.28;}player.position.set(0,0,7);player.rotation.y=0;
// Environment mist layers and drifting moths
const mistMat=new THREE.MeshBasicMaterial({color:0xa8b5a8,transparent:true,opacity:.075,depthWrite:false,side:THREE.DoubleSide});for(let i=0;i<8;i++){let m=new THREE.Mesh(new THREE.PlaneGeometry(13,2.5),mistMat);m.position.set((Math.random()-.5)*16,.85+Math.random()*1,-4-Math.random()*18);m.rotation.y=(Math.random()-.5)*.55;scene.add(m);m.userData.phase=Math.random()*6.3;}
const moths=[];for(let i=0;i<19;i++){let m=new THREE.Group();let core=new THREE.Mesh(new THREE.SphereGeometry(.035,5,4),mats.moth);m.add(core);for(let s of [-1,1]){let w=new THREE.Mesh(new THREE.PlaneGeometry(.14,.08),mats.moth);w.position.x=s*.07;w.rotation.y=s*.18;m.add(w);}m.position.set((Math.random()-.5)*14,.6+Math.random()*3,-3-Math.random()*19);m.userData={origin:m.position.clone(),phase:Math.random()*6.28,speed:.4+Math.random()};scene.add(m);moths.push(m);}
const interactables=[{id:'monolith',name:'MONOLITO TALLADO',x:0,z:-7,dist:2.6},{id:'relic',name:'RELIQUIA OLVIDADA',x:-7,z:-12,dist:2.5},{id:'woman',name:'LA ANCIANA',x:7,z:-13,dist:2.8}];
let started=false,dialogueOpen=false,clue=false,relicFound=false,choiceMade=false,choice='',ending=false,near=null,moveX=0,moveY=0,cameraYaw=0,cameraPitch=.12,skill=false;const inventory=[];let currentNode=null;
const $=s=>document.querySelector(s);const toast=$('#toast');let toastTimer;function showToast(t){toast.textContent=t;toast.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.add('hidden'),1800);}
function addItem(name,desc,icon='◇'){if(inventory.some(i=>i.name===name))return;inventory.push({name,desc,icon});renderInventory();}
function renderInventory(){$('#item-count').textContent=inventory.length;$('#inventory-items').innerHTML=inventory.length?inventory.map(i=>`<div class="inventory-item"><span class="item-icon">${i.icon}</span><div><strong>${i.name}</strong><small>${i.desc}</small></div></div>`).join(''):'<p class="empty-inventory">Aún está vacía.</p>';}
function setObjective(t){$('#objective-text').textContent=t;}
function openDialogue(speaker,text,choices=[],onContinue=null){dialogueOpen=true;$('#speaker').textContent=speaker;$('#dialogue-text').textContent=text;$('#dialogue').classList.remove('hidden');$('#choices').innerHTML='';$('#continue').classList.toggle('hidden',!onContinue);currentNode=onContinue;choices.forEach((c,i)=>{let b=document.createElement('button');b.className='choice-button';b.innerHTML=`<span class="choice-num">0${i+1}</span>${c.label}`;b.onclick=()=>{if(c.action)c.action();};$('#choices').appendChild(b);});}
function closeDialogue(){dialogueOpen=false;$('#dialogue').classList.add('hidden');currentNode=null;}
$('#continue').onclick=()=>{if(currentNode)currentNode();};
function doInteract(){if(dialogueOpen||ending)return;if(!near){showToast('No hay nada que examinar aquí.');return;}if(near.id==='monolith'){if(!clue){clue=true;skill=true;addItem('Marca de ceniza','Tres muescas bajo una raíz.','⌁');setObjective('Busca entre las ruinas. Algo refleja la luna.');openDialogue('EL MONOLITO','La piedra está tibia, aunque la noche muerde. Tres muescas rodean un nombre borrado. Al tocarlas, una palabra se forma detrás de tus dientes: «debajo».',[{label:'Memorizar las tres muescas',action:()=>{closeDialogue();showToast('La forma queda grabada en tu memoria.');}}]);}else openDialogue('EL MONOLITO','Las tres muescas parecen distintas ahora. Una gota oscura asciende por la piedra, contra la gravedad.',[{label:'Apartar la mano',action:closeDialogue}]);}
else if(near.id==='relic'){if(!relicFound){relicFound=true;addItem('Astilla de vidrio negro','Una reliquia que guarda un murmullo.','◈');relic.rotation.x+=.7;setObjective('Encuentra a quien conoce este lugar.');const success=skill;openDialogue('LA RELIQUIA','Bajo el pedestal, encuentras un vidrio oscuro. El susurro no viene de la reliquia: viene de algo que espera al otro lado de tu reflejo.',[{label:'Guardar la astilla',action:()=>{closeDialogue();if(success)showToast('Algo en la ciénaga ha oído tu recuerdo.');}}]);}else openDialogue('LA RELIQUIA','El vidrio devuelve tu rostro con un instante de retraso.',[{label:'Dejarlo en su sitio',action:closeDialogue}]);}
else if(near.id==='woman'){if(!choiceMade){openDialogue('LA ANCIANA','No mires las luces entre los árboles. No son estrellas caídas. Son ojos que olvidaron cómo cerrar.',[{label:'¿Qué hago con esta astilla?',action:()=>openDialogue('LA ANCIANA','Ah. Ya has encontrado el diente. Puedes devolverlo al agua, o llevarlo hasta donde el sendero se parte.',[{label:'Devolverla. Que el agua la recuerde.',action:()=>{choice='water';choiceMade=true;openDialogue('LA ANCIANA','Entonces el barro beberá en silencio. Toma mi hilo; no dejes que te llamen por el nombre que perdiste.',[{label:'Aceptar el hilo',action:()=>{addItem('Hilo de la anciana','Un hilo gris, frío como la luna.','〰');closeDialogue();setObjective('Sigue el sendero del eco o el de la sal.');}}]);}},{label:'Llevarla al umbral. Quiero oír.',action:()=>{choice='threshold';choiceMade=true;openDialogue('LA ANCIANA','La curiosidad es una puerta que se abre hacia dentro. Lleva la astilla. Cuando la piedra cante, no respondas con tu voz.',[{label:'Recordar la advertencia',action:()=>{closeDialogue();setObjective('Sigue el sendero del eco o el de la sal.');}}]);}}]),{label:'¿Quién soy?',action:()=>{let response=skill?'Lo que recuerdas no es tu nombre. Pero es suficiente para que el bosque te tema.':'Eres la pregunta que la ciénaga dejó en la orilla. Aún no has aprendido a escucharla.';openDialogue('LA ANCIANA',response,[{label:'Hablar de la reliquia',action:()=>doWomanAgain()}]);}}]);}else openDialogue('LA ANCIANA',choice==='water'?'El agua ya conoce tu decisión. No la hagas repetirla.':'El umbral te ha oído. No le regales también tu nombre.',[{label:'Dejarla en paz',action:closeDialogue}]);}}
function doWomanAgain(){openDialogue('LA ANCIANA','No mires las luces entre los árboles. No son estrellas caídas. Son ojos que olvidaron cómo cerrar.',[{label:'¿Qué hago con esta astilla?',action:()=>doInteractWomanChoices()}]);}
function doInteractWomanChoices(){// Shortcut to the actual choice options after the initial exchange.
openDialogue('LA ANCIANA','Puedes devolverla al agua, o llevarla hasta donde el sendero se parte.',[{label:'Devolverla. Que el agua la recuerde.',action:()=>{choice='water';choiceMade=true;openDialogue('LA ANCIANA','Entonces el barro beberá en silencio. Toma mi hilo; no dejes que te llamen por el nombre que perdiste.',[{label:'Aceptar el hilo',action:()=>{addItem('Hilo de la anciana','Un hilo gris, frío como la luna.','〰');closeDialogue();setObjective('Sigue el sendero del eco o el de la sal.');}}]);}},{label:'Llevarla al umbral. Quiero oír.',action:()=>{choice='threshold';choiceMade=true;openDialogue('LA ANCIANA','La curiosidad es una puerta que se abre hacia dentro. Lleva la astilla. Cuando la piedra cante, no respondas con tu voz.',[{label:'Recordar la advertencia',action:()=>{closeDialogue();setObjective('Sigue el sendero del eco o el de la sal.');}}]);}}]);}
function reachEnding(gate){if(!choiceMade){showToast('La anciana aún espera una respuesta.');return;}ending=true;$('#ending-screen').classList.remove('hidden');let truth=skill&&relicFound;let title,copy,note;if(choice==='water'&&gate.x<0){title='LO QUE EL AGUA GUARDA';copy=truth?'La astilla se hunde. Tres anillos se abren en el agua; al cuarto, una voz pronuncia un nombre que no recuerdas haber perdido.':'La superficie se cierra sobre la astilla. Por un momento, los árboles inclinan sus ramas hacia ti.';note='La anciana ya no está. En el barro, unas huellas caminan junto a las tuyas.';$('#ending-symbol').textContent='〰';}else if(choice==='threshold'&&gate.x<0){title='EL ECO RESPONDE';copy=truth?'Las marcas del monolito brillan bajo tu piel. Algo contesta desde la otra orilla, usando tu propia voz.':'El umbral vibra. Oyes una respuesta, demasiado lejana para comprenderla.';note='Al amanecer, la astilla sigue en tu mano. Ahora pesa como una promesa.';$('#ending-symbol').textContent='◈';}else if(choice==='threshold'){title='LA SAL EN LA LENGUA';copy='El aire se llena de un sabor antiguo. La astilla se aclara y, detrás de ella, algo abre un ojo sin párpado.';note=truth?'La anciana dejó un hilo en tu muñeca. Está tenso, apuntando hacia casa.':'No sabes si has encontrado la salida o una forma nueva de entrar.';$('#ending-symbol').textContent='✳';}else{title='EL SENDERO VACÍO';copy='El agua no te sigue. El bosque tampoco se aparta. Caminas hasta que el silencio deja de tener forma.';note='En tu bolsa, el hilo gris se ha vuelto una raíz.';$('#ending-symbol').textContent='⌁';}$('#ending-title').textContent=title;$('#ending-copy').textContent=copy;$('#ending-note').textContent=note;}
function findNearest(){let found=null,dist=99;for(const o of interactables){let d=Math.hypot(player.position.x-o.x,player.position.z-o.z);if(d<o.dist&&d<dist){found=o;dist=d;}}if(choiceMade){for(const g of gates){let d=Math.hypot(player.position.x-g.x,player.position.z-g.z);if(d<2.8&&d<dist){found={id:'gate',name:g.label,gate:g};dist=d;}}}return found;}
function interact(){near=findNearest();if(near?.id==='gate')reachEnding(near.gate);else doInteract();}
$('#action-button').addEventListener('pointerdown',e=>{e.preventDefault();interact();});window.addEventListener('keydown',e=>{if(e.code==='KeyE'||e.code==='Space'){e.preventDefault();interact();}if(e.code==='KeyI'){toggleInventory();}if(e.code==='Escape'){closeDialogue();$('#inventory-panel').classList.add('hidden');}});
function toggleInventory(){$('#inventory-panel').classList.toggle('hidden');}$('#inventory-toggle').onclick=toggleInventory;$('#close-inventory').onclick=toggleInventory;
// Mobile virtual joystick and swipe camera
const joy=$('#joystick'),knob=$('#joy-knob');let joyPointer=null;joy.addEventListener('pointerdown',e=>{e.preventDefault();joyPointer=e.pointerId;joy.setPointerCapture(e.pointerId);updateJoy(e);});joy.addEventListener('pointermove',e=>{if(e.pointerId===joyPointer)updateJoy(e);});function resetJoy(){joyPointer=null;moveX=moveY=0;knob.style.transform='translate(-50%,-50%)';}joy.addEventListener('pointerup',resetJoy);joy.addEventListener('pointercancel',resetJoy);function updateJoy(e){let r=joy.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),len=Math.hypot(dx,dy),max=39;if(len>max){dx*=max/len;dy*=max/len;}moveX=dx/max;moveY=dy/max;knob.style.transform=`translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px))`;}
let dragging=false,lastX=0,lastY=0;canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;dragging=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!dragging)return;let dx=e.clientX-lastX,dy=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;cameraYaw-=dx*.006;cameraPitch=THREE.MathUtils.clamp(cameraPitch+dy*.002,-.04,.45);});canvas.addEventListener('pointerup',()=>dragging=false);canvas.addEventListener('pointercancel',()=>dragging=false);
const keys={};window.addEventListener('keydown',e=>{keys[e.code]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();});window.addEventListener('keyup',e=>keys[e.code]=false);
let last=performance.now(),walk=0;function frame(now){requestAnimationFrame(frame);let dt=Math.min((now-last)/1000,.04);last=now;let ix=moveX,iy=moveY;if(keys.KeyA||keys.ArrowLeft)ix-=1;if(keys.KeyD||keys.ArrowRight)ix+=1;if(keys.KeyW||keys.ArrowUp)iy-=1;if(keys.KeyS||keys.ArrowDown)iy+=1;let mag=Math.hypot(ix,iy);if(mag>1){ix/=mag;iy/=mag;}if(started&&!dialogueOpen&&!ending&&mag>.05){let angle=cameraYaw;let dx=(ix*Math.cos(angle)+iy*Math.sin(angle)),dz=(-ix*Math.sin(angle)+iy*Math.cos(angle));let nx=player.position.x+dx*3.1*dt,nz=player.position.z+dz*3.1*dt;
// Collide with trees, ruins and world edges
let blocked=false;for(let ob of interactables){if(Math.hypot(nx-ob.x,nz-ob.z)<.7){blocked=true;break;}}for(let x=-18;x<=18;x+=4.2){for(let z=-20;z<12;z+=4.6){if(Math.abs(x)<4&&z>0)continue;if(Math.hypot(nx-x,nz-z)<.7){blocked=true;break;}}}if(!blocked){player.position.x=THREE.MathUtils.clamp(nx,-19,19);player.position.z=THREE.MathUtils.clamp(nz,-24,12);}let targetYaw=Math.atan2(dx,dz)+Math.PI;avatar.rotation.y=THREE.MathUtils.damp(avatar.rotation.y,targetYaw,.14,dt);walk+=dt*10;avatar.position.y=Math.abs(Math.sin(walk))*.045;}
